INSERT INTO projects (id, user_id, title, summary, description, category, location, tags, status, cover_image_url, goal_amount, created_at, updated_at) VALUES
('a1a1a1a1-a1a1-41a1-a1a1-a1a1a1a1a1a1', '11111111-1111-4111-8111-111111111111', 'Ecoliá: Plataforma de Reciclaje Urbano Inteligente', 'Conectando hogares, clasificadores locales y centros de reciclaje con sensores IoT y recompensas digitales.', 'Ecoliá busca revolucionar el reciclaje en las ciudades de Latinoamérica. Más del 80% de los residuos reciclables termina en vertederos por falta de separación en origen y logística ineficiente. Nuestra solución: puntos limpios inteligentes con sensores, app móvil de recompensas y red de recolectores con rutas optimizadas.', 'tech', 'Ciudad de México', '["iot","sostenibilidad","reciclaje","movilidad"]', 'building', 'https://images.unsplash.com/photo-1532996122724-e3c354a0b15b?w=800&auto=format&fit=crop&q=80', '25000.00', 1760500000000, 1760500000000),
('b2b2b2b2-b2b2-42b2-a2b2-b2b2b2b2b2b2', '22222222-2222-4222-8222-222222222222', 'Mercado Raíces: De la Granja a la Mesa sin Intermediarios', 'Mercado digital directo que permite a pequeños agricultores vender sus cosechas orgánicas a restaurantes y familias.', 'Queremos empoderar al agricultor local eliminando las capas de intermediarios que encarecen los alimentos. Los productores publican su oferta semanal, los chefs y familias hacen pedidos conjuntos y entregamos en camionetas eléctricas agrupadas por distrito.', 'business', 'Bogotá', '["agricultura","alimentación","comercio-justo","logistica"]', 'running', 'https://images.unsplash.com/photo-1488459716781-31db52582fe9?w=800&auto=format&fit=crop&q=80', '15000.00', 1760500000000, 1760500000000),
('c3c3c3c3-c3c3-43c3-a3c3-c3c3c3c3c3c3', '33333333-3333-4333-8333-333333333333', 'Galería Urbana VR: Reivindicando el Arte Mural Calle', 'Escaneo 3D y plataforma inmersiva en realidad virtual para preservar y democratizar el arte urbano de Latinoamérica.', 'El arte urbano es efímero y a menudo destruido por el desarrollo inmobiliario. Nuestra propuesta digitaliza en ultra-alta definición los murales más emblemáticos de Buenos Aires, Medellín y CDMX, creando galerías accesibles para escuelas y amantes del arte de todo el mundo.', 'art', 'Buenos Aires', '["vr","arte-urbano","cultura","3d"]', 'idea', 'https://images.unsplash.com/photo-1561055657-b9e0bf0fa360?w=800&auto=format&fit=crop&q=80', '10000.00', 1760500000000, 1760500000000),
('d4d4d4d4-d4d4-44d4-a4d4-d4d4d4d4d4d4', '11111111-1111-4111-8111-111111111111', 'EduRed: Alfabetización Digital para Comunidades Rurales', 'Kits educativos offline accionados por energía solar con servidores Raspberry Pi cargados con Wikipedia y cursos interactivos.', 'Millones de niños en zonas rurales carecen de acceso estable a internet. EduRed transmite una red Wi-Fi local desde un dispositivo solar compacto, entregando contenidos pedagógicos de máxima calidad sin costo de datos.', 'social', 'Oaxaca, México', '["educacion","hardware","solar","social-impact"]', 'building', 'https://images.unsplash.com/photo-1509062522246-3755977927d7?w=800&auto=format&fit=crop&q=80', '18000.00', 1760500000000, 1760500000000);
