('18181818-1818-4818-8818-181818181818', 'b2b2b2b2-b2b2-42b2-a2b2-b2b2b2b2b2b2', '11111111-1111-4111-8111-111111111111', 'RESOURCE', 'Tengo acceso a un lote de sensores de temperatura IoT y GPS que les pueden servir para las camionetas refrigeradas.', NULL, 0, 'pending', 1760500000000, 1760500000000),
('29292929-2929-4929-8929-292929292929', 'c3c3c3c3-c3c3-43c3-a3c3-c3c3c3c3c3c3', '22222222-2222-4222-8222-222222222222', 'COLLABORATE', 'Conozco varios colectivos de artistas en Bogotá que estarían fascinados de subir sus murales a la plataforma.', NULL, 0, 'pending', 1760500000000, 1760500000000);
INSERT INTO project_updates (id, project_id, title, content, links, created_at, updated_at) VALUES
('3a3a3a3a-3a3a-43a3-aa3a-3a3a3a3a3a3a', 'a1a1a1a1-a1a1-41a1-a1a1-a1a1a1a1a1a1', '¡Primer prototipo físico de contenedor instalado en la UAM!', 'Hoy instalamos el primer prototipo de Ecoliá en la Universidad Autónoma. En solo 4 horas recibimos 120 kg de botellas PET y 45 estudiantes se registraron en la prueba piloto.', '[{"label":"Ver fotos del prototipo","url":"https://github.com"}]', 1760500000000, 1760500000000),
('4b4b4b4b-4b4b-44b4-ab4b-4b4b4b4b4b4b', 'a1a1a1a1-a1a1-41a1-a1a1-a1a1a1a1a1a1', 'Llegamos al 40% de la meta de validación comunitaria', 'Queremos agradecer a todos los mentores y colaboradores que se han sumado esta semana. Estamos ultimando los esquemas del circuito impreso del sensor de peso.', '[]', 1760500000000, 1760500000000),
('5c5c5c5c-5c5c-45c5-ac5c-5c5c5c5c5c5c', 'b2b2b2b2-b2b2-42b2-a2b2-b2b2b2b2b2b2', 'Alianza firmada con 15 productores de la sabana de Bogotá', 'Esta semana concretamos el acuerdo de precio justo con la asociación de horticultores locales. Comenzaremos las pruebas de reparto el próximo mes.', '[{"label":"Reporte de Prensa","url":"https://news.ycombinator.com"}]', 1760500000000, 1760500000000);
